import{_ as r,l as i,o as e,c as f,v as n,p as l,x as t,d as s,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Huffman 编码","description":"","frontmatter":{"title":"Huffman 编码","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/huffman-coding.md","filePath":"cs/huffman-coding.md","lastUpdated":1789023840000}'),p={name:"cs/huffman-coding.md"};function u(h,a,c,_,E,H){const o=i("Mermaid");return e(),f("div",null,[a[1]||(a[1]=n('<h1 id="huffman-编码" tabindex="-1">Huffman 编码 <a class="header-anchor" href="#huffman-编码" aria-label="Permalink to &quot;Huffman 编码&quot;">​</a></h1><div class="epigraph"><p>每次合并两个最轻的权，得到的前缀码在整数码长、逐符号意义下期望最短；它逼近熵，但不拆开一个符号内部的比特。</p><footer>—— 据 Huffman, A Method for the Construction of Minimum-Redundancy Codes, 1952；Cover and Thomas 整理</footer></div><p>上一课<a href="/cs/source-coding-theorem">信源编码定理</a> 给出 \\(H\\le L\\lt H+1\\) 的空间。缺口是构造：<strong>Huffman 算法</strong>达到所有前缀码中最小的 \\(L=\\sum p_i\\ell_i\\)。不重证 Kraft，不写算术（下一课才把码长变成分数比特）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>已知有限字母表与 \\(p_i\\gt 0\\)。前缀码 \\(\\iff\\) 二叉树叶。期望长度 = 加权路径长。Huffman：把最小的两权合成一父节点，权相加，递归。最优性：存在最优码使两最小符号互为兄弟，故归纳成立。码长 \\(\\ell_i=\\lceil-\\log p_i\\rceil\\) 的 Shannon 码未必最优，Huffman 才是。</p><p>当某 \\(p_i\\) 很大，\\(L\\) 仍 \\(\\ge 1\\cdot p_{\\max}\\)，离 \\(H\\) 可差近 1。这是「不拆符号」的代价，留给算术编码。</p><h3 id="不是「频繁的字母用短-ascii」" tabindex="-1">不是「频繁的字母用短 ASCII」 <a class="header-anchor" href="#不是「频繁的字母用短-ascii」" aria-label="Permalink to &quot;不是「频繁的字母用短 ASCII」&quot;">​</a></h3><p>ASCII 定长。Huffman 相对给定 \\(p\\)；换语料要换树。自适应 Huffman 点名，本课静态。</p><p><span class="marginnote">Huffman 1952。Cover–Thomas 第 5 章证明最优。Kraft 等号：完全树。本课不把堆实现当主线，算法课已有优先队列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对小分布手算一棵树，核对 \\(L\\) 与 \\(H\\)。强调：平局时树不唯一，\\(L\\) 相同。译码：从根走比特。不要用哈夫曼树去纠错——距离无保证。</p>',11)),(e(),l(m,null,{default:t(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%A6%82%E7%8E%87%E8%A1%A8%22%5D%20--%3E%20MERGE%5B%22%E5%8F%8D%E5%A4%8D%E5%90%88%E5%B9%B6%E4%B8%A4%E6%9C%80%E5%B0%8F%E6%9D%83%22%5D%0A%20%20MERGE%20--%3E%20TREE%5B%22%E5%89%8D%E7%BC%80%E6%A0%91%22%5D%0A%20%20TREE%20--%3E%20L%5B%22%E6%9C%9F%E6%9C%9B%E9%95%BF%E5%BA%A6%E6%9C%80%E4%BC%98%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最优前缀码给出可即时译码的比特流，无需逗号。块 Huffman（对 \\(n\\) 元组）把 \\(L/n\\) 推向 \\(H\\)，代价是表指数。实践中宁可用自适应或算术。本课把「整数码长最优」钉死。</p><p>与<a href="/cs/regex-lexer">词法 DFA</a> 无关：那是识别，这是编码。</p><p>兄弟性质：最稀的两个符号在最优树里深度相同且为兄弟，故贪心合并合法。规范 Huffman 只存码长，译码表更紧，本课不写比特格式。\\(p_i\\) 为 \\(2\\) 的负幂时 \\(L=H\\)。否则整数码长是网格，算术下一课拆开格子。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证算术，不引入规范 Huffman 的比特级格式。不把 JPEG 的表当定义。后课默认：逐符号前缀最优 = Huffman；分数比特下一课。下一课算术编码。</p><p>最优是相对前缀码与给定 \\(p\\) 的期望长度，不是相对算术码，也不是相对 \\(K(x)\\)。换语料必须换树或改成自适应。纠错不要用这棵树的码字距离。</p><p>上一课留下的缺口在本课收口；「Huffman 编码」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Huffman 合并最小权，得到最优前缀码。</li><li>\\(L\\) 仍可能比 \\(H\\) 差近 1；块或算术再逼近。</li><li>相对给定分布；不是字符集。</li><li>出处：Huffman, 1952；Cover and Thomas。</li></ul>',10))])}const T=r(p,[["render",u]]);export{C as __pageData,T as default};
